        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Se vouloir libre, c'est aussi vouloir les autres libres", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "On ne naît pas femme : on le devient.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Le propre des manies et des vices, c'est d'engager la liberté à vouloir ce qu'elle ne veut pas.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "La femme est vouée à l'immoralité parce que la morale consiste pour elle à incarner une inhumaine entité : la femme forte, la mère admirable, l'honnête femme etc.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "C'est la femme qui travaille – paysanne, chimiste ou écrivain – qui a la grossesse la plus facile du fait qu'elle ne se fascine pas sur sa propre personne ; c'est la femme qui a la vie personnelle la plus riche qui donnera le plus à l'enfant et qui lui demandera le moins, c'est celle qui acquiert dans l'effort, dans la lutte, la connaissance des vraies valeurs humaines qui sera la meilleure éducatrice.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Jusqu’ici les possibilités de la femme ont été étouffées et perdues pour l’humanité et il est grand temps dans son intérêt et dans celui de tous qu’on lui laisse enfin courir toutes ses chances.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Dans les deux sexes se jouent les mêmes drames de la chair et de l’esprit, de la finitude et de la transcendance, les deux sont rongés par le temps, guettés par la mort, ils ont un même essentiel besoin de l’autre ; ils peuvent tirer de leur liberté la même gloire ; s’ils savaient la goûter, ils ne seraient plus tentés de se discuter de fallacieux privilèges ; et la fraternité pourrait alors naître entre eux.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "C'est par le travail que la femme a en grande partie franchi la distance qui la séparait du mâle; c'est le travail qui peut seul lui garantir une liberté concrète.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "En effet, pour devenir un créateur il ne suffit pas de se cultiver, c'est-à-dire d'intégrer à sa vie des spectacles, des connaissances : il faut que la culture soit appréhendée à travers le libre mouvement d'une transcendance : il faut que l'esprit avec toutes ses richesses se jette vers un ciel vide qu'il lui appartient de peupler : mais si mille liens ténus le rattachent à la terre, son élan est brisé.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "La femme libre est seulement en train de naître.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Je suis un intellectuel. Ça m'agace qu'on fasse de ce mot une insulte : les gens ont l'air de croire que le vide de leur cerveau leur meuble les couilles.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "N’oubliez jamais qu’il suffira d’une crise politique, économique ou religieuse pour que les droits des femmes soient remis en question. Ces droits ne sont jamais acquis. Vous devrez rester vigilantes votre vie durant.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Mais il y eut un livre où je crus reconnaître mon visage et mon destin : ''Litlle Women'', de Louisa Alcott.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Je m'identifiai passionnément à Joe, l’intellectuelle. Brusque, anguleuse, Joe se perchait, pour lire au faîte des arbres, elle était bien plus garçonnière et plus hardie que moi; mais je partageais son horreur de la couture et du ménage, son amour des livres.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Je me passais très bien de Dieu et si j'utilisais son nom, c'était pour désigner un vide qui avait à mes yeux l'éclat de la plénitude.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Je trouvais d'autant plus affreux de mourir que je ne voyais pas de raison de vivre.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Il n'y a pas de mort naturelle : rien de ce qui arrive à l'homme n'est jamais naturel puisque sa présence met le monde en question. Tous les hommes sont mortels : mais pour chaque homme sa mort est un accident et, même s'il la connaît et y consent, une violence indue.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Les jeunes femmes ont un sens aigu de ce qu'il convient de faire et de ne pas faire quand on a cessé d'être jeune.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "La vieillesse: de loin on la prend pour une institution: mais ce sont des gens jeunes qui soudain se trouvent être vieux.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Je suis sensible aux blâmes et aux louanges.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Vieillir, c'est se définir et se réduire .", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "La seule chose importante à la fois neuve et importante qui puisse m'arrive, c'est le malheur .", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "La création est aventure, elle est jeunesse et liberté .", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Ce qui contribue à déformer l'image des écrivains, c'est le nombre de de mythomanes qu'ils nous font intervenir dans leurs contes .", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Être brutalement précipité de la catégorie des individus actifs dans celle des inactifs et classé comme vieux, subir une diminution consternante de ses ressources et de son niveau de vie, c'est dans l'immense majorité des cas un drame qui entraîne de graves conséquences psychologiques et morales. Il frappe essentiellement les hommes. Les femmes vivent plus longtemps : ce sont les grandes vieillardes solitaires qui constituent la couche la plus défavorisée de la population.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Un million de femmes se font avorter chaque année en France. Elles le font dans des conditions dangereuses en raison de la clandestinité à laquelle elles sont condamnées, alors que cette opération, pratiquée sous contrôle médical, est des plus simples. On fait le silence sur ces millions de femmes.Je déclare que je suis l'une d'elles. Je déclare avoir avorté. De même que nous réclamons le libre accès aux moyens anticonceptionnels, nous réclamons l'avortement libre.", Author = "Simone de Beauvoir" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Il y a chez Simone de Beauvoir une noblesse placide.", Author = "Charles Dantzig" },
